<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el panel de administración.');}
$_SESSION['last_seen']=time();
if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET'){http_response_code(405);header('Allow: GET');exit('Esta página es de consulta.');}
$id=filter_var($_GET['id']??'',FILTER_VALIDATE_INT);$type=$_GET['tipo']??'';
if(!$id||$id<1||!in_array($type,['participation','account'],true)){http_response_code(404);exit('No existe esa solicitud.');}
try{
 if($type==='participation'){$q=db()->prepare('SELECT * FROM leads WHERE id=?');$q->execute([$id]);$item=$q->fetch(PDO::FETCH_ASSOC);}
 else{$q=db()->prepare('SELECT r.*,a.display_name AS account_name,a.email,a.status AS account_status,a.email_verified_at,dt.display_name AS destination_name,ct.label AS category_label FROM business_account_applications r JOIN accounts a ON a.id=r.account_id JOIN destination_translations dt ON dt.destination_id=r.destination_id AND dt.locale="es" JOIN service_category_translations ct ON ct.category_code=r.category_code AND ct.locale="es" WHERE r.id=?');$q->execute([$id]);$item=$q->fetch(PDO::FETCH_ASSOC);}
 if(!$item){http_response_code(404);exit('No existe esa solicitud.');}
 $business=null;$membership=false;$subscription=null;
 if($type==='account'&&$item['business_id']){
  $q=db()->prepare('SELECT b.id,b.publication_status,b.claim_status,b.information_status,t.display_name FROM businesses b JOIN business_translations t ON t.business_id=b.id AND t.locale="es" WHERE b.id=?');$q->execute([$item['business_id']]);$business=$q->fetch(PDO::FETCH_ASSOC);
  $q=db()->prepare('SELECT COUNT(*) FROM business_account_memberships WHERE business_id=? AND account_id=? AND status="active"');$q->execute([$item['business_id'],$item['account_id']]);$membership=(int)$q->fetchColumn()>0;
  $q=db()->prepare('SELECT plan_code,status FROM business_subscriptions WHERE business_id=? ORDER BY id DESC LIMIT 1');$q->execute([$item['business_id']]);$subscription=$q->fetch(PDO::FETCH_ASSOC);
 }
}catch(PDOException $error){http_response_code(503);exit('No se pudo consultar la solicitud. Revisa el estado de la base de datos.');}
function request_detail_value(mixed $value):string {return is_scalar($value)?(string)$value:json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);}
$detailLabels=['application_type'=>['request_new'=>'Incorporación de negocio nuevo','claim_existing'=>'Asociación de negocio existente'],'relationship_code'=>['owner'=>'Propietaria/o','legal_representative'=>'Representante legal','authorized_administrator'=>'Administradora/or autorizada/o','authorized_representative'=>'Representante autorizada/o'],'status'=>['pending'=>'Pendiente','in_review'=>'En revisión','approved'=>'Aprobada','not_approved'=>'No aprobada','nuevo'=>'Nuevo','revisado'=>'Revisado','contactado'=>'Contactado','archivado'=>'Archivado']];
$fields=$type==='participation'?['business'=>'Negocio declarado','name'=>'Persona','municipality'=>'Destino declarado','category'=>'Categoría','email'=>'Correo','phone'=>'Teléfono','phone_type'=>'Tipo de teléfono','interest'=>'Tipo de solicitud','description'=>'Descripción enviada','status'=>'Estado de seguimiento','created_at'=>'Fecha UTC','participation_version'=>'Alcance aceptado','consent_version'=>'Versión del consentimiento']:['business_name'=>'Nombre enviado','destination_name'=>'Destino','category_label'=>'Categoría','application_type'=>'Tipo de solicitud','relationship_code'=>'Relación declarada','message'=>'Mensaje enviado','contact_phone'=>'Teléfono declarado','status'=>'Estado de solicitud','created_at'=>'Fecha UTC'];
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Revisar solicitud | Administración</title><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page"><h1>Revisar solicitud #<?=esc($id)?></h1><?php require __DIR__.'/_navigation.php'; ?>
<p><a href="<?=$type==='participation'?'index.php':'solicitudes-cuenta.php'?>">Volver a solicitudes</a>. Esta página muestra información privada; no cambia estados ni envía correos.</p>
<section class="account-portal-card"><h2>Enviado por la persona</h2><p>Estos son los datos conservados de la solicitud; no son una certificación de su contenido.</p><dl class="admin-request-detail"><?php foreach($fields as $key=>$label):?><dt><?=esc($label)?></dt><dd><?=esc(request_detail_value($detailLabels[$key][$item[$key]??'']??($item[$key]??'Sin información')))?></dd><?php endforeach ?></dl>
<?php if($type==='participation'):?><p>Solicita contacto: <?=!empty($item['wants_contact'])?'Sí':'No'?>. Estado de seguimiento y envío de correo son procesos distintos.</p>
<?php else:$details=json_decode($item['business_details_json']??'{}',true)?:[];?>
<h3>Plan solicitado</h3><?php $choice=$details['requested_subscription']??[];if($choice):?><p>Plan: <?=esc(['free'=>'Gratis','featured'=>'Destacado','page'=>'Página Comercial','page_premium'=>'Premium'][$choice['plan_code']??'']??($choice['plan_code']??'Sin información'))?> · Periodicidad: <?=esc(['monthly'=>'Mensual','quarterly'=>'Trimestral','semiannual'=>'Semestral','annual'=>'Anual'][$choice['billing_frequency']??'']??'No aplica / sin informar')?></p><?php else:?><p>No se conserva una elección de plan.</p><?php endif ?><p>La elección enviada no demuestra que exista una suscripción creada.</p>
<?php require __DIR__.'/_application-details.php'; ?>
<?php $q=db()->prepare('SELECT id,original_name,evidence_type FROM business_account_application_evidence WHERE application_id=?');$q->execute([$id]);$evidence=$q->fetchAll(PDO::FETCH_ASSOC);?>
<h3>Documentos privados</h3><?php if(!$evidence):?><p>No hay documentos registrados.</p><?php else:?><ul><?php foreach($evidence as $document):?><li><a href="representacion-evidencia.php?id=<?=esc($document['id'])?>" target="_blank" rel="noopener"><?=esc($document['original_name'])?> ↗</a></li><?php endforeach ?></ul><?php endif ?>
<?php endif ?></section>
<?php if($type==='account'):?><section class="account-portal-card"><h2>Cuenta y asociación registradas</h2><p><?=esc($item['account_name'])?> · <?=esc($item['email'])?></p><p>Cuenta: <?=esc($item['account_status'])?> · Correo: <?=empty($item['email_verified_at'])?'Pendiente de verificar':'Verificado'?>.</p><p><?=$membership?'Esta cuenta tiene una asociación activa con la ficha.':'No hay una asociación activa de esta cuenta con la ficha.'?> La asociación no certifica titularidad.</p></section>
<section class="account-portal-card"><h2>Ficha y suscripción actuales</h2><?php if($business):?><p><?=esc($business['display_name'])?> · <?=esc($business['publication_status'])?></p><p>Información: <?=esc($business['information_status'])?> · Representación: <?=esc($business['claim_status'])?></p><p>Suscripción: <?=esc($subscription?($subscription['plan_code'].' · '.$subscription['status']):'Sin suscripción registrada')?></p><a class="pill light compact" href="negocios.php?id=<?=esc($business['id'])?>" target="_blank" rel="noopener">Abrir negocio ↗</a> <a class="pill light compact" href="suscripciones.php?id=<?=esc($business['id'])?>" target="_blank" rel="noopener">Ver suscripción y revisión ↗</a><?php else:?><p>La solicitud todavía no tiene una ficha disponible. No se creó otra ficha al abrir esta página.</p><?php endif ?></section>
<section class="notice"><h2>Siguiente paso administrativo</h2><p><?=esc(in_array($item['status'],['pending','in_review'],true)?'Consultar la solicitud en la pantalla operativa existente para continuar su revisión.':(!$membership&&$business?'Solicitud cerrada sin asociación activa: revisar el historial antes de corregir datos.':($business&&$business['publication_status']!=='published'?'La ficha no está publicada. Consultar su revisión individual.':'Consultar el registro y su historial.')))?></p><a class="pill light compact" href="solicitudes-cuenta.php">Abrir solicitudes de cuenta</a></section><?php endif ?>
</main></body></html>
